import Dexie, { type Table } from 'dexie';

interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
}

interface LocalOrder {
  id: string;
  tableNumber: number;
  items: OrderItem[];
  status: 'pending' | 'synced' | 'failed';
  clientUpdatedAt: number;
}

interface SyncQueueItem {
  id: string;
  entity: 'orders';
  action: 'INSERT' | 'UPDATE' | 'DELETE';
  payload: Record<string, unknown>;
  createdAt: number;
  attempts: number;
}

class AppDatabase extends Dexie {
  orders!: Table<LocalOrder, string>;
  syncQueue!: Table<SyncQueueItem, string>;

  constructor() {
    super('RestaurantDB');
    this.version(1).stores({
      orders: 'id, tableNumber, status, clientUpdatedAt',
      syncQueue: 'id, entity, createdAt, attempts'
    });
  }
}

export const db = new AppDatabase();

export async function createOrderOptimistic(orderData: Omit<LocalOrder, 'status' | 'clientUpdatedAt'>) {
  const now = Date.now();
  const newOrder: LocalOrder = {
    ...orderData,
    status: 'pending',
    clientUpdatedAt: now
  };

  const queueTask: SyncQueueItem = {
    id: crypto.randomUUID(),
    entity: 'orders',
    action: 'INSERT',
    payload: newOrder as unknown as Record<string, unknown>,
    createdAt: now,
    attempts: 0
  };

  // Atomic transaction ensures outbox item exists if local record exists
  await db.transaction('rw', [db.orders, db.syncQueue], async () => {
    await db.orders.put(newOrder);
    await db.syncQueue.put(queueTask);
  });

  return newOrder;
}
